export function ReachOutLeadingIcon({
  name,
  size = 16,
  className,
}: {
  name: string
  size?: number
  className?: string
}) {
  const stroke = { size, strokeWidth: 2, className }
  switch (name) {
    case 'mail':
      return <Mail {...stroke} />
    case 'github':
      return <SvgGitHub size={size} className={className} />
    case 'linkedin':
      return <SvgLinkedIn size={size} className={className} />
    case 'substack':
      return <SvgSubstack size={size} className={className} />
    case 'x':
      return <SvgX size={size} className={className} />
    case 'reddit':
      return <SvgReddit size={size} className={className} />
    case 'youtube':
      return <SvgYouTube size={size} className={className} />
    case 'producthunt':
      return <SvgProductHunt size={size} className={className} />
    case 'devto':
      return <SvgDevTo size={size} className={className} />
    case 'figma':
      return <SvgFigma size={size} className={className} />
    case 'bsky':
      return <SvgBsky size={size} className={className} />
    case 'gdev':
      return <SvgGdev size={size} className={className} />
    case 'microsoft':
      return <SvgMicrosoft size={size} className={className} />
    case 'aws':
      return <SvgAws size={size} className={className} />
    case 'lovable':
      return <SvgLovable size={size} className={className} />
    case 'cursor':
      return <SvgCursor size={size} className={className} />
    case 'medium':
      return <SvgMedium size={size} className={className} />
    case 'npm':
      return <SvgNpm size={size} className={className} />
    case 'kick':
      return <SvgKick size={size} className={className} />
    default:
      return null
  }
}

export default ReachOutLeadingIcon


